'use strict';
// Fonts embedded as data (OFL licences in assets/fonts) so they load even from file://
const FONT_DATA = [
  ['PressStart', '400', 'U+0000-00FF', ''],
  ['PressStart', '400', 'U+0100-024F', ''],
  ['Pixelify', '500', 'U+0000-00FF,U+2000-206F', ''],
  ['Pixelify', '500', 'U+0100-024F', ''],
  ['Pixelify', '700', 'U+0000-00FF,U+2000-206F', ''],
  ['Pixelify', '700', 'U+0100-024F', ''],
  ['Bungee', '400', 'U+0000-00FF', ''],
  ['Exo2', '600', 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD', ''],
  ['Exo2', '800', 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD', ''],
];
function loadFonts() {
  if (!window.FontFace) return Promise.resolve();
  const bin = (b64) => { const s = atob(b64); const a = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); return a.buffer; };
  return Promise.all(FONT_DATA.map(([fam, weight, range, b64]) => {
    const f = new FontFace(fam, bin(b64), { weight, unicodeRange: range });
    document.fonts.add(f);
    return f.load().catch(() => null);
  }));
}
